// Expo config plugin: give the generated android/app/build.gradle a real
// `release` signing config. android/ is regenerated by `expo prebuild --clean`
// (CNG, gitignored), so a hand edit there would be lost on every prebuild.
//
// Credentials are never in this repo. They're read at Gradle time from
// ~/.gradle/gradle.properties (or -P flags / ORG_GRADLE_PROJECT_* env vars):
//   JEWELCHAT_UPLOAD_STORE_FILE=/absolute/path/to/jewelchat-upload.keystore
//   JEWELCHAT_UPLOAD_STORE_PASSWORD=...
//   JEWELCHAT_UPLOAD_KEY_ALIAS=jewelchat-upload
//   JEWELCHAT_UPLOAD_KEY_PASSWORD=...
// If they aren't set, the release build keeps the debug key (Expo's default),
// so `expo run:android --variant release` still works locally. That AAB is
// NOT uploadable to Play. See docs/play-store-release.md.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// @jewelchat/release-signing';

const SIGNING_CONFIG = `
        release {
            ${MARKER}
            if (project.hasProperty('JEWELCHAT_UPLOAD_STORE_FILE')) {
                storeFile file(JEWELCHAT_UPLOAD_STORE_FILE)
                storePassword JEWELCHAT_UPLOAD_STORE_PASSWORD
                keyAlias JEWELCHAT_UPLOAD_KEY_ALIAS
                keyPassword JEWELCHAT_UPLOAD_KEY_PASSWORD
            }
        }`;

function applyReleaseSigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;

  // 1. Add signingConfigs.release next to the template's debug config.
  const debugConfig = /(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/;
  if (!debugConfig.test(gradle)) {
    throw new Error('withReleaseSigning: signingConfigs.debug block not found in app/build.gradle');
  }
  let out = gradle.replace(debugConfig, `$1${SIGNING_CONFIG}`);

  // 2. Point buildTypes.release at it, but only when the keystore is configured.
  const releaseUsesDebug = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;
  if (!releaseUsesDebug.test(out)) {
    throw new Error('withReleaseSigning: buildTypes.release signingConfig line not found in app/build.gradle');
  }
  out = out.replace(
    releaseUsesDebug,
    `$1signingConfig project.hasProperty('JEWELCHAT_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`,
  );
  return out;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== 'groovy') {
      throw new Error('withReleaseSigning: only Groovy build.gradle is supported');
    }
    mod.modResults.contents = applyReleaseSigning(mod.modResults.contents);
    return mod;
  });
};

module.exports.applyReleaseSigning = applyReleaseSigning;
